TLM.f("Tempora/Pasc0-0",{"officium":"Dominica Resurrectionis","rule":["Sequentia","Credo","Prefatio=Pasch"],"sections":{"Introitus":[{"k":"ref","la":"Ps 138:18; 138:5-6"},{"k":"text","la":"Resurréxi, et adhuc tecum sum, allelúja: posuísti super me manum tuam, allelúja: mirábilis facta est sciéntia tua, allelúja, allelúja."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Resurréxi, et adhuc tecum sum, allelúja: posuísti super me manum tuam, allelúja: mirábilis facta est sciéntia tua, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérna die per Unigénitum tuum æternitátis nobis áditum, devícta morte, reserásti: vota nostra, quæ præveniéndo aspíras, étiam adjuvándo proséquere."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios."},{"k":"ref","la":"1 Cor 5:7-8"},{"k":"text","la":"Fratres: Expurgáte vetus ferméntum, ut sitis nova conspérsio, sicut estis ázymi. Etenim Pascha nostrum immolátus est Christus. Itaque epulémur: non in ferménto véteri, neque in ferménto malítiæ et nequítiæ: sed in ázymis sinceritátis et veritátis."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps. 117:24; 117:1"},{"k":"text","la":"Hæc dies, quam fecit Dóminus: exsultémus et lætémur in ea."},{"k":"text","la":"Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericórdia ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"1 Cor 5:7"},{"k":"text","la":"Pascha nostrum immolátus est Christus.","mark":"V"}],"Sequentia":[{"k":"text","la":"Víctimæ pascháli laudes ímmolent Christiáni."},{"k":"text","la":"Agnus rédemit oves: Christus ínnocens Patri reconciliávit peccatóres."},{"k":"text","la":"Mors et vita duéllo conflixére mirándo: dux vitæ mórtuus regnat vivus."},{"k":"text","la":"Dic nobis, María, quid vidísti in via?"},{"k":"text","la":"Sepúlcrum Christi vivéntis et glóriam vidi resurgéntis."},{"k":"text","la":"Angélicos testes, sudárium et vestes."},{"k":"text","la":"Surréxit Christus, spes mea: præcédet vos in Galilǽam."},{"k":"text","la":"Scimus Christum surrexísse a mórtuis vere: tu nobis, victor Rex, miserére. Amen. Allelúja."},{"k":"rubric","la":"Sequentia dicitur usque ad Sabbatum in Albis inclusive."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Marcum."},{"k":"ref","la":"Marc 16:1-7"},{"k":"text","la":"In illo témpore: María Magdaléne et María Jacóbi et Salóme emérunt arómata, ut veniéntes úngerent Jesum. Et valde mane una sabbatórum, véniunt ad monuméntum, orto jam sole. Et dicébant ad ínvicem: Quis revólvet nobis lápidem ab óstio monuménti? Et respiciéntes vidérunt revolútum lápidem. Erat quippe magnus valde. Et introëúntes in monuméntum vidérunt júvenem sedéntem in dextris, coopértum stola cándida, et obstupuérunt. Qui dicit illis: Nolíte expavéscere: Jesum quǽritis Nazarénum, crucifíxum: surréxit, non est hic, ecce locus, ubi posuérunt eum. Sed ite, dícite discípulis ejus et Petro, quia præcédit vos in Galilǽam: ibi eum vidébitis, sicut dixit vobis."}],"Offertorium":[{"k":"ref","la":"Ps. 75:9-10"},{"k":"text","la":"Terra trémuit, et quiévit, dum resúrgeret in judício Deus, allelúja."}],"Secreta":[{"k":"text","la":"Súscipe, quǽsumus, Dómine, preces pópuli tui cum oblatiónibus hostiárum: ut, Paschálibus initiáta mystériis, ad æternitátis nobis medélam, te operánte, profíciant."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"1 Cor 5:7-8"},{"k":"text","la":"Pascha nostrum immolátus est Christus, allelúja: itaque epulémur in ázymis sinceritátis et veritátis, allelúja, allelúja, allelúja."}],"Postcommunio":[{"k":"text","la":"Spíritum nobis, Dómine, tuæ caritátis infúnde: ut, quos sacraméntis paschálibus satiásti, tua fácias pietáte concordes."},{"k":"macro","name":"Per Dominum eiusdem"}],"Præfatio ins":[{"k":"text","la":"Te quidem, Dómine, omni témpore, sed in hac potíssimum die"}]},"hr":{"98124cc2a332dc33":{"t":"Ps 138, 18 i 5-6, Ps 138, 1-2\n(Ps 138, 18 et 5-6) Uskrsnuh i stalno sam s tobom, <i>aleluja</i>.\nStavio si na me svoju ruku, <i>aleluja</i>.\nDivno se pokazala tvoja mudrost, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 18 et 5-6) Uskrsnuh i stalno sam s tobom, <i>aleluja</i>.\nStavio si na me svoju ruku, <i>aleluja</i>.\nDivno se pokazala tvoja mudrost, <i>aleluja</i>, <i>aleluja</i>.","kn":"(PS'. 138, 18, 6). Uskrsnuh i s Tobom sam, .Aleluja; poistavio .si svoju ruku -na me, Aleluja: divno se očitovala Tvoja mudrost, Aleluja, Aleluja. (Ps. 138, 1). Gospodine, Ti si ' me kušao. Tebi je Uskrs poznat moj počinak i moje iisknsnuće. Slava Ocu . . . CJskrsnuh . . . Aleluja, Aleluja.","knRef":"Kniewald 1942, str. 298–299 (snimka 150) (OCR)"},"ab80edd594a7def7":{"t":"<i>Pomolimo se</i>.\nBože koji si na današnji dan po svojemu Jedinorođencu pobijedio smrt i ponovo nam otvorio vrata vječnosti, prati svojom pomoću želje koje nam prethodno nadahnjuješ.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si nam na današnji dan po svojem Jedincu, pobjedniku smrti, opet otvorio vrata, vječnosti, ispuni svojom moću naše želje, koje nam udahnjuješ svojom milošću Po istom G. n. 1. K.","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"00200109cc2d8ac4":{"t":"1 Kor 5, 7-8\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo: Očistite stari kvasac da, kad ste već beskvasni, postanete novo tijesto, jer je žrtvovan Krist, naše vazmeno janje. Zato svetkujmo blagdan, ali ne sa starim kvascem, s kvascem zlobe i grijeha, nego s beskvasnim kruhom iskrenosti i istine.","kn":"Čitanje poslanice bi. Pavia apostola Korinćanima (I, 5, 7-8). Braćo! Očistite stari kvasac, da, kao što ste bes'kvasni, postanete novo tijesto, jer je žrtvovan Krist, naše vazmeno janje. Zato goštimo se; ne u .starom kvascu niti u kvascu zlobe i bezakonja, nego u beskvasnom kruhu iskrenosti i istine.","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"9c329614674c73e5":{"t":"Ps 117, 24 et 1\nOvo je dan što ga učini Gospodin! Kličimo i radujmo se danas! – Hvalite Gospodina, jer je dobar, jer je dovijeka njegovo milosrđe.\n\n1 Kor 5, 7\n<i>Aleluja</i>, <i>aleluja</i>.\nŽrtvovan je Krist naše vazmeno janje.","v":"∅ → aleluia aleluia","kn":"(Ps. 117, 24, 1). Ovo je dan, koji nam je pripravio Gospodin, kličimo i radujmo se. Hvalite Gospodina, jer je dobar, jer je dovijeka milosrđe n,jegovo.\n\nAleluja. Žrtvovano je naše vazmeno janje, Krist!","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"a670bd50efcad44c":{"t":"Svetoj Žrtvi uskrsnici dajte slavu krštenici!<i>\n</i>\nJanje ovce oslobodi Krist nas grješne preporodi.<i>\n</i>\nSa životom smrt se sasta i čudesna borba nasta: Vođa živih pade tada i živ živcat opet vlada.<i>\n</i>\nMarijo, o reci što je? Što ti oko vidjelo je?<i>\n</i>\nGrob ja vidjeh Krista Boga, svijetlu slavu uskrsloga.<i>\n</i>\nAnđele i platno bijelo u kom bješe sveto tijelo.<i>\n</i>\nUfanje mi uskrslo je Krist, moj Gospod i sve moje! Pred vama će tamo gdje je cvjetna strana Galileje.<i>\n</i>\nZnamo da si doistine uskrsnuo Božji Sine! Pobjedniče, Kralju divan, budi nama milostivan!<i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"454bd739939f7489":{"t":"Mk 16, 1-7\nSlijedi sveto Evanđelje po Marku. U ono vrijeme: Marija Magdalena i Marija Jakovljeva majka i Saloma kupe pomasti i pođu da pomažu Isusa. I prvoga dana po suboti, vrlo rano, kad je sunce izlazilo, dođu na grob. Među sobom su govorile: Tko će nam odvaliti kamen s ulaza groba? – Pogledaju i vide da je već odvaljen kamen koji je bio vrlo velik. Uđu u grob, opaze mladića obučena u bijelu haljinu gdje sjedi s desne strane i uplaše se. On im reče: Nemojte se bojati! Vi tražite Isusa Nazarećanina raspetoga. Uskrsnuo je! Nema ga ovdje. Evo mjesta gdje je bio položen. Nego idite, recite njegovim učenicima, posebno Petru, da odlazi pred vama u Galileju. Ondje ćete ga vidjeti, kako vam je rekao.","kn":"t Slijedi sveto evanđelje po Marku (16, 1-7). U ono vrijeme kuipile su Marija Magdalena i Marija Jatoovljeva pomasti, da odu i pomažu Isusa. I prvo'ga dana PO suboti vrlo rano, kad je sunce već izašlo, dođoše k grobu. Govorile su među sobom; Tko će nam odvaliti kamen s vrata groba? I kad pogledaše, vidješe, da je odvaljen kamen, koji je bio vrlo velik. I uđoše u grob i vidješe u bijelu haljinu obučena mladića, gdje sjedi s desne strane i uplašiše se. On im reče: Nemojte se plašiti! Vi tražite Isusa Nazarečanina, raspetoga. Uskrsno je, nema ga ovdje! Evo mjesta, kamo su ga položili. Nego idite, kažite njegovim učenicima i Petru, da ide pred vama u Galileju. Tamo ćete ga vidjeti, kako vam je rekao.","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"9bfaafab34d97306":{"t":"Ps 75, 9-10\nZemlja se potrese i smiri kad ustade Bog da sudi, <i>aleluja</i>.","kn":"(Ps. 75, 9, 10). Zemlja se potrese^ i umuknu, kad usta Bog, da izvrši pravdu, Aleluja.","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"b270585b70eae500":{"t":"Sa žrtvenim prinosima primi, molimo, Gospodine, i molitve svoga puka, da posvećene uskrsnim otajstvima, po tvojem djelovanju budu nama na pomoć za vječnost.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo, Gospodine, ' molitve svoga puka, koji Ti prinosi ove žrtve, da nam posvećene vazmenim otajstvima Po Tvojem djelovanju budu na vjekovitu 'Pomoć, po G. n. I. K.","knRef":"Kniewald 1942, str. 300–301 (snimka 151) (OCR)"},"687cae1ead8b8c38":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>danas</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"f9ea3eb4aceff6ad":{"t":"Ps 109, 3\nŽrtvovan je Krist, naše vazmeno janje, <i>aleluja</i>.\nZato svetkujmo blagdan s beskvasnim kruhom iskrenosti i istine, <i>aleluja</i>, <i>aleluja</i>, <i>aleluja</i>.","kn":"(I. Kor. 5, 7, 8). Naše je žrtveno janje Krist, Aleluja. Dokle svetkujmo; ne u starom kvascu, niti u kvascu zloće i pakosti, nego u beskvasnom kruhu iskrenosti , i istine. Aleluja.","knRef":"Kniewald 1942, str. 302–303 (snimka 152) (OCR)"},"be472ea2d68699bb":{"t":"<i>Pomolimo se</i>.\nUlij nam, Gospodine, Duha ljubavi svoje i složi svojom blagošću one koje si nasitio uskrsnim tajnama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ulij nam, Gospoidine, duh ljubavi svoje, da svojom milostivošću učiniš složnima, koje si nahranio vazmenim tajnama, po G. n.","knRef":"Kniewald 1942, str. 298–299 (snimka 150) (OCR)"}}});
